nextflow_process {
    name "SNIFFLES2"
    script "../main.nf"
    process "SNIFFLES2"

    test("call one synthetic deletion") {
        options "-with-docker"

        when {
            process {
                """
                input[0] = record(
                    id: 'sample',
                    bam: file("${moduleDir}/tests/data/reads.bam", checkIfExists: true),
                    bai: file("${moduleDir}/tests/data/reads.bam.bai", checkIfExists: true),
                    ref: file("${moduleDir}/tests/data/reference.fa", checkIfExists: true),
                    fai: file("${moduleDir}/tests/data/reference.fa.fai", checkIfExists: true)
                )
                input[1] = 40
                input[2] = 160
                input[3] = 0
                """
            }
        }

        then {
            assert process.success
            def vcf = file(process.out[0].vcf[0])
            assert vcf.text.readLines().count { line -> !line.startsWith('#') } == 1
            assert vcf.text.contains('SVTYPE=DEL')
            assert vcf.text.contains('--minsvlen 40')
            assert vcf.text.contains('--cluster-merge-pos 160')
            assert vcf.text.contains('--input reads.bam')
        }
    }
}
